    samen: "Bij A is weggelaten dat Elkana twee vrouwen had en dat Peninna Hanna plaagde (1 Samuël 1:2, 6–7). Ook de zonde van Eli’s zonen staat er niet in, en wat de HEERE die nacht tegen Samuël zegt: Hij zal het huis van Eli straffen (1 Samuël 2:12–17, 22–25; 3:11–14). Aan het eind van hoofdstuk 3 weet heel Israël dat Samuël een profeet van de HEERE is (3:20). Een vraag om samen over te praten: waarom noemt Hanna haar zoon Samuël? (1:20)",
